#!/usr/bin/env bash
set -euo pipefail
# GENERATED by dsl/gunbc/fleet_converge_emit.dag (gunbc.fleet_converge_emit). DO NOT HAND-EDIT.
# Regime-2 pure projection of the gunbc.host_converge policy. Run per-host as the blessed ctrl
# shell transport; emits converge-receipt lines on stdout (EMIT is the single authority; the
# ctrl reconciler aligns to gunbc_host_converge_receipt_grammar_marker with no fallback).
# Ordering invariant: caps-before-widen (runner_count is applied LAST).

host_failed=0
applied=0; drifted=0; any_absent=0; verdict=converged; effective=

emit_receipt() {
  printf 'converge-receipt host=%s slice=%s knob=%s desired=%s effective=%s verdict=%s\n' "$1" "$2" "$3" "$4" "$5" "$6"
}

record() {
  applied=$((applied + 1))
  if [ "$1" != "converged" ]; then drifted=$((drifted + 1)); fi
  if [ "$1" = "absent" ]; then any_absent=1; fi
}

host_begin() {
  applied=0; drifted=0; any_absent=0
}

host_summary() {
  if [ "$drifted" -eq 0 ]; then verdict=converged
  elif [ "$any_absent" -eq 1 ]; then verdict=absent
  else verdict=drifted; fi
  printf 'converge-receipt host=%s applied=%s drifted=%s verdict=%s\n' "$1" "$applied" "$drifted" "$verdict"
  if [ "$drifted" -ne 0 ]; then host_failed=1; fi
}

# verdict realizes gunbc.host_converge.converge_verdict (single authority): empty=absent, equal=converged, else=drifted.
decide_verdict() {
  if [ -z "$1" ]; then verdict=absent
  elif [ "$1" = "$2" ]; then verdict=converged
  else verdict=drifted; fi
}

converge_slice_property() {
  # host slice knob unit property apply_value expected_effective desired_display
  systemctl set-property "$4" "$5=$6" >/dev/null 2>&1 || true
  effective="$(systemctl show "$4" --property="$5" --value 2>/dev/null || true)"
  if [ -z "$effective" ]; then effective=ABSENT; verdict=absent; else decide_verdict "$effective" "$7"; fi
  emit_receipt "$1" "$2" "$3" "$8" "$effective" "$verdict"
  record "$verdict"
}

converge_per_slot_cap() {
  # host slice knob dropin_path instance_glob property bytes
  # template drop-in (future instances, inert until restart) + set-property per active instance (effective now)
  mkdir -p "$(dirname "$4")"
  printf '[Service]\n%s=%s\n' "$6" "$7" > "$4"
  systemctl daemon-reload >/dev/null 2>&1 || true
  n=0; all_ok=1; effective=ABSENT
  for unit in $(systemctl list-units --type=service --state=active --no-legend "$5" 2>/dev/null | awk '{print $1}'); do
    n=$((n + 1))
    systemctl set-property "$unit" "$6=$7" >/dev/null 2>&1 || true
    eff="$(systemctl show "$unit" --property="$6" --value 2>/dev/null || true)"
    effective="$eff"
    if [ "$eff" != "$7" ]; then all_ok=0; fi
  done
  if [ "$n" -eq 0 ]; then effective=ABSENT; verdict=absent
  elif [ "$all_ok" -eq 1 ]; then verdict=converged
  else verdict=drifted; fi
  emit_receipt "$1" "$2" "$3" "$7" "$effective" "$verdict"
  record "$verdict"
}

converge_runner_width() {
  # host slice knob instance_glob desired_count
  # UP (per-slot idempotent): enable+start each registered slot 01..desired that is inactive; active slots are skipped (harmless no-op).
  # Reconciles by smallest unit -- a half-active fleet enables only the inactive half, regardless of the aggregate count.
  # Unprovisioned slots fail to start (non-fatal) and surface as a drifted/absent width verdict below -> run the install path (Part B: secret-bearing config.sh register).
  i=1
  while [ "$i" -le "$5" ]; do
    inst="actions-runner@$1-$(printf '%02d' "$i").service"
    systemctl is-active --quiet "$inst" || systemctl enable --now "$inst" >/dev/null 2>&1 || true
    i=$((i + 1))
  done
  # DOWN: drain any surplus beyond desired, highest-NN first (drain-before-stop: SIGTERM to Runner.Listener, never SIGKILL), then disable.
  current=$(systemctl list-units --type=service --state=active --no-legend "$4" 2>/dev/null | awk 'END{print NR}')
  current=${current:-0}
  if [ "$current" -gt "$5" ]; then
    systemctl list-units --type=service --state=active --no-legend "$4" 2>/dev/null | awk '{print $1}' | sort -r | head -n "$((current - $5))" | while IFS= read -r unit; do
      systemctl stop "$unit" || true
      systemctl disable "$unit" >/dev/null 2>&1 || true
    done
  fi
  effective=$(systemctl list-units --type=service --state=active --no-legend "$4" 2>/dev/null | awk 'END{print NR}')
  effective=${effective:-0}
  decide_verdict "$effective" "$5"
  emit_receipt "$1" "$2" "$3" "$5" "$effective" "$verdict"
  record "$verdict"
}

converge_jobserver_tokens() {
  # host slice knob env_file env_key service desired_count  (FIFO-safe: shrink by attrition on restart between builds)
  mkdir -p "$(dirname "$4")"
  printf '%s=%s\n' "$5" "$7" > "$4"
  systemctl restart "$6" >/dev/null 2>&1 || true
  effective="$(grep -E "^$5=" "$4" 2>/dev/null | head -n1 | cut -d= -f2 | tr -d ' ' || true)"
  if [ -z "$effective" ]; then effective=ABSENT; verdict=absent; else decide_verdict "$effective" "$7"; fi
  emit_receipt "$1" "$2" "$3" "$7" "$effective" "$verdict"
  record "$verdict"
}

converge_verify_only_cap() {
  # host slice knob slice_unit property desired  (CARRY+VERIFY ONLY: NEVER set-property; the spawn path owns the write)
  scope="$(systemctl show "$4" --property=ConsistsOf --value 2>/dev/null | tr ' ' '\n' | grep -m1 '\.scope$' || true)"
  if [ -z "$scope" ]; then effective=ABSENT; verdict=absent;
  else
    effective="$(systemctl show "$scope" --property="$5" --value 2>/dev/null || true)"
    if [ -z "$effective" ]; then effective=ABSENT; verdict=absent; else decide_verdict "$effective" "$6"; fi
  fi
  emit_receipt "$1" "$2" "$3" "$6" "$effective" "$verdict"
  record "$verdict"
}

emit_sessions_membership() {
  # host slice_cgroup legacy_cgroup  (membership signal for the OomdEnforced guard; EMPTY slice => 0, not error)
  in_slice=$(ls -d "$2"/docker-*.scope 2>/dev/null | wc -l | tr -d ' ' || true)
  in_slice=${in_slice:-0}
  legacy=$(ls -d "$3"/docker-*.scope 2>/dev/null | wc -l | tr -d ' ' || true)
  legacy=${legacy:-0}
  if [ "$in_slice" -gt 0 ]; then verdict=converged; else verdict=absent; fi
  printf 'converge-receipt host=%s slice=sessions sessions_in_slice=%s sessions_legacy_flat=%s verdict=%s\n' "$1" "$in_slice" "$legacy" "$verdict"
  record "$verdict"
}

# Per-host scope: runs only the section matching arg 1, else $(hostname -s), else ALL sections if unmatched.
target_host="${1:-$(hostname -s 2>/dev/null || echo unknown)}"
case "$target_host" in srv1|srv2) run_all=0;; *) run_all=1;; esac
if [ "$run_all" = "1" ]; then echo "fleet-converge: host '$target_host' not in fleet; running ALL host sections (pass a host name as arg 1 to scope to one)" >&2; fi
if [ "$run_all" = "1" ] || [ "$target_host" = "srv1" ]; then
host_begin "srv1"
converge_slice_property "srv1" "runner" "runner_slice_cap_bytes" "system-actions-runner.slice" "MemoryMax" "85899345920" "85899345920" "85899345920"
converge_per_slot_cap "srv1" "runner" "per_slot_memory_max_bytes" "/etc/systemd/system/actions-runner@.service.d/20-fleet-width.conf" "actions-runner@srv1-*.service" "MemoryMax" "8589934592"
converge_per_slot_cap "srv1" "runner" "per_slot_memory_swap_max_bytes" "/etc/systemd/system/actions-runner@.service.d/30-fleet-swap.conf" "actions-runner@srv1-*.service" "MemorySwapMax" "0"
converge_slice_property "srv1" "runner" "cpu_weight" "system-actions-runner.slice" "CPUWeight" "100" "100" "100"
converge_jobserver_tokens "srv1" "runner" "build_tokens" "/etc/default/ctrl-jobserver" "CTRL_JOBSERVER_TOKENS" "ctrl-jobserver.service" "128"
converge_runner_width "srv1" "runner" "runner_count" "actions-runner@srv1-*.service" "10"
converge_slice_property "srv1" "sessions" "slice_max_bytes" "sessions.slice" "MemoryMax" "21474836480" "21474836480" "21474836480"
converge_verify_only_cap "srv1" "sessions" "per_session_max_bytes" "sessions.slice" "MemoryMax" "10737418240"
converge_slice_property "srv1" "sessions" "oom_pressure_kill" "sessions.slice" "ManagedOOMMemoryPressure" "kill" "kill" "true"
converge_slice_property "srv1" "sessions" "oom_pressure_limit_pct" "sessions.slice" "ManagedOOMMemoryPressureLimit" "60%" "2576980377" "60"
converge_slice_property "srv1" "sessions" "cpu_weight" "sessions.slice" "CPUWeight" "1000" "1000" "1000"
emit_sessions_membership "srv1" "/sys/fs/cgroup/sessions.slice" "/sys/fs/cgroup/system.slice"
host_summary "srv1"
fi
if [ "$run_all" = "1" ] || [ "$target_host" = "srv2" ]; then
host_begin "srv2"
converge_slice_property "srv2" "runner" "runner_slice_cap_bytes" "system-actions-runner.slice" "MemoryMax" "85899345920" "85899345920" "85899345920"
converge_per_slot_cap "srv2" "runner" "per_slot_memory_max_bytes" "/etc/systemd/system/actions-runner@.service.d/20-fleet-width.conf" "actions-runner@srv2-*.service" "MemoryMax" "8589934592"
converge_per_slot_cap "srv2" "runner" "per_slot_memory_swap_max_bytes" "/etc/systemd/system/actions-runner@.service.d/30-fleet-swap.conf" "actions-runner@srv2-*.service" "MemorySwapMax" "0"
converge_slice_property "srv2" "runner" "cpu_weight" "system-actions-runner.slice" "CPUWeight" "100" "100" "100"
converge_jobserver_tokens "srv2" "runner" "build_tokens" "/etc/default/ctrl-jobserver" "CTRL_JOBSERVER_TOKENS" "ctrl-jobserver.service" "128"
converge_runner_width "srv2" "runner" "runner_count" "actions-runner@srv2-*.service" "10"
converge_slice_property "srv2" "sessions" "slice_max_bytes" "sessions.slice" "MemoryMax" "21474836480" "21474836480" "21474836480"
converge_verify_only_cap "srv2" "sessions" "per_session_max_bytes" "sessions.slice" "MemoryMax" "10737418240"
converge_slice_property "srv2" "sessions" "oom_pressure_kill" "sessions.slice" "ManagedOOMMemoryPressure" "kill" "kill" "true"
converge_slice_property "srv2" "sessions" "oom_pressure_limit_pct" "sessions.slice" "ManagedOOMMemoryPressureLimit" "60%" "2576980377" "60"
converge_slice_property "srv2" "sessions" "cpu_weight" "sessions.slice" "CPUWeight" "1000" "1000" "1000"
emit_sessions_membership "srv2" "/sys/fs/cgroup/sessions.slice" "/sys/fs/cgroup/system.slice"
host_summary "srv2"
fi
exit "$host_failed"
